// WriteFileAt writes data to path by opening an os.Root at path's parent
// directory and writing the final component through it. It is the drop-in
// replacement for os.WriteFile: same create/truncate semantics, same
// permission handling (perm applies only when the file is created), and the
// same unwrapped errors, so callers may keep using os.IsNotExist/errors.Is.
//
// The root confines the write to the parent directory, so it cannot be
// redirected outside it by a swapped or symlinked final component between
// path resolution and open (TOCTOU) — the write counterpart of the read-side
// confinement in settings.readConfined.
//
// Note the asymmetry between the two halves of the path: the parent directory
// is resolved normally (os.OpenRoot follows symlinks in the root path itself,
// so a symlinked ~/.claude still works), but the final component may not
// escape it. A file symlinked out of its directory by a dotfile manager is
// therefore rejected rather than followed; callers that write user-managed
// config must surface that error rather than swallow it.
func WriteFileAt(path string, data []byte, perm os.FileMode) error {
	root, err := os.OpenRoot(filepath.Dir(path))
	if err != nil {
		return err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer root.Close()

	return WriteFile(root, filepath.Base(path), data, perm)
}
