func write(path string) error {
	root, err := os.OpenRoot(filepath.Dir(path))
	if err != nil {
		return fmt.Errorf("openroot: %w", err)
	}
	defer root.Close()
	f, err := root.OpenFile(filepath.Base(path), os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600)
	if err != nil {
		return fmt.Errorf("openfile: %w", err)
	}
	defer f.Close()
	_, err = f.Write([]byte("hello"))
	return err
}

func main() {
	base, _ := os.MkdirTemp("", "probe")
	defer os.RemoveAll(base)

	// 1. symlinked PARENT directory
	real := filepath.Join(base, "realdir")
	os.MkdirAll(real, 0o755)
	link := filepath.Join(base, "linkdir")
	os.Symlink(real, link)
	fmt.Println("1. symlinked parent dir      :", errStr(write(filepath.Join(link, "f.txt"))))

	// 2. final component is symlink ESCAPING the root
	outside := filepath.Join(base, "outside.txt")
	os.WriteFile(outside, []byte("x"), 0o600)
	os.Symlink(outside, filepath.Join(real, "escape.txt"))
	fmt.Println("2. final comp escapes root   :", errStr(write(filepath.Join(real, "escape.txt"))))

	// 3. final component is symlink INSIDE the root
	os.WriteFile(filepath.Join(real, "target.txt"), []byte("x"), 0o600)
	os.Symlink("target.txt", filepath.Join(real, "inside.txt"))
	err := write(filepath.Join(real, "inside.txt"))
	got, _ := os.ReadFile(filepath.Join(real, "target.txt"))
	fmt.Printf("3. final comp inside root    : %s (target now=%q)\n", errStr(err), string(got))

	// 4. parent dir missing entirely (os.WriteFile parity: ENOENT)
	err = write(filepath.Join(base, "nope", "f.txt"))
	fmt.Println("4. missing parent dir        :", errStr(err), "| IsNotExist:", os.IsNotExist(err))
	errW := os.WriteFile(filepath.Join(base, "nope", "f.txt"), []byte("x"), 0o600)
	fmt.Println("   os.WriteFile equivalent   :", errStr(errW), "| IsNotExist:", os.IsNotExist(errW))

	// 5. perm on existing file preserved (os.WriteFile parity)
	ex := filepath.Join(real, "perm.txt")
	os.WriteFile(ex, []byte("x"), 0o644)
	write(ex)
	st, _ := os.Stat(ex)
	fmt.Printf("5. existing file mode kept   : %v\n", st.Mode().Perm())

	// 6. bare relative filename (Dir returns ".")
	os.Chdir(real)
	fmt.Println("6. bare relative filename    :", errStr(write("bare.txt")))
}

func errStr(err error) string {
	if err == nil {
		return "OK"
	}
	return "ERR: " + err.Error()
}
