static volatile int gate;
static int op;
static int succ, e_exist, e_noent, e_other, last_errno;
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;

static void record(int ok) {
    pthread_mutex_lock(&mu);
    if (ok) succ++;
    else if (errno == EEXIST) e_exist++;
    else if (errno == ENOENT) e_noent++;
    else { e_other++; last_errno = errno; }
    pthread_mutex_unlock(&mu);
}

static void *worker(void *arg) {
    long idx = (long)arg;
    char src[64];
    while (!gate) {}
    switch (op) {
    case 0: record(mkdirat(dirfd_g, "n", 0700) == 0); break;
    case 1: record(symlinkat("some-target", dirfd_g, "n") == 0); break;
    case 2: record(linkat(dirfd_g, "src", dirfd_g, "n", 0) == 0); break;
    case 3:
        snprintf(src, sizeof src, "s%ld", idx);
        record(renameat(dirfd_g, src, dirfd_g, "n") == 0);
        break;
    }
    return NULL;
}

static void run(const char *label, int which) {
    op = which;
    int t_succ = 0, t_exist = 0, t_noent = 0, t_other = 0;
    int multi_winner = 0, wrong_end_state = 0;

    for (int t = 0; t < TRIALS; t++) {
        char tmpl[] = "/tmp/scXXXXXX";
        char *dir = mkdtemp(tmpl);
        dirfd_g = open(dir, O_RDONLY | O_DIRECTORY);

        if (which == 2) { int fd = openat(dirfd_g, "src", O_RDWR|O_CREAT, 0600); if (fd>=0) close(fd); }
        if (which == 3) {
            for (long i = 0; i < NT; i++) {
                char s[64]; snprintf(s, sizeof s, "s%ld", i);
                int fd = openat(dirfd_g, s, O_RDWR|O_CREAT, 0600); if (fd>=0) close(fd);
            }
        }

        succ = e_exist = e_noent = e_other = 0; gate = 0;
        pthread_t th[NT];
        for (long i = 0; i < NT; i++) pthread_create(&th[i], NULL, worker, (void*)i);
        gate = 1;
        for (int i = 0; i < NT; i++) pthread_join(th[i], NULL);

        t_succ += succ; t_exist += e_exist; t_noent += e_noent; t_other += e_other;
        // rename legitimately lets every thread succeed (it replaces); others must have exactly 1
        if (which != 3 && succ > 1) multi_winner++;
        struct stat st;
        if (fstatat(dirfd_g, "n", &st, AT_SYMLINK_NOFOLLOW) != 0) wrong_end_state++;

        // cleanup
        char p[512];
        snprintf(p, sizeof p, "%s/n", dir);
        if (which == 0) rmdir(p); else unlink(p);
        for (long i = 0; i < NT; i++) { char s[600]; snprintf(s, sizeof s, "%s/s%ld", dir, i); unlink(s); }
        snprintf(p, sizeof p, "%s/src", dir); unlink(p);
        close(dirfd_g); rmdir(dir);
    }
    printf("  %-12s ok=%5d EEXIST=%5d ENOENT=%5d other=%d(errno %d)  multi-winner=%d  missing-after=%d\n",
           label, t_succ, t_exist, t_noent, t_other, last_errno, multi_winner, wrong_end_state);
}

int main(void) {
    printf("%d threads x %d trials racing ONE name, darwin\n", NT, TRIALS);
