//   2. on EEXIST: openat(no O_CREAT) -> correct (plain open of existing file)
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <unistd.h>
#define NT 20
#define TRIALS 300
static int dfd, mode_g, fails, enoent, other;
static volatile int gate;
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;

static int open_naive(void) { return openat(dfd, "n", O_RDWR|O_CREAT, 0600); }

static int open_twostep(void) {
    int fd = openat(dfd, "n", O_RDWR|O_CREAT|O_EXCL, 0600);
    if (fd >= 0) return fd;
    if (errno != EEXIST) return -1;
    return openat(dfd, "n", O_RDWR, 0);   // exists now; no O_CREAT
